<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserTemporalPasswordAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserTemporalPasswordAccessor trait.
 *
 * Covers null default, string/VO assignment via withTemporalPassword,
 * getTemporalPassword/temporalPassword accessors, and isTemporalPasswordChanged with/without original.
 */
class UserTemporalPasswordAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTemporalPassword creates a new instance with the TemporalPassword set
     * from a string value, and getTemporalPassword returns the primitive string.
     */
    public function testWithTemporalPasswordFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserTemporalPasswordAccessorUnitTest();

        // Act
        $result = $holder->withTemporalPassword(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isTemporalPassword());
    }
    /**
     * Asserts that withtemporalPassword has access to the value object
     * from a string value, and getTemporalPassword returns the primitive string.
     */
    public function testWithTemporalPasswordFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserTemporalPasswordAccessorUnitTest();

        // Act
        $result = $holder->withTemporalPassword(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->temporalPassword()->value());
    }
    public function testChangedTemporalPassword(): void
    {
        // Arrange
        $holder = new ImplWithUserTemporalPasswordAccessorUnitTest();
        $original = $holder->withTemporalPassword( true);
        $same = $holder->withTemporalPassword( true);
        $modified = $holder->withTemporalPassword(false);

        // Act
        $unchanged = $holder->isTemporalPasswordChanged();
        $withSame = $original->isTemporalPasswordChanged( $same );
        $withDiferent = $original->isTemporalPasswordChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserTemporalPasswordAccessorUnitTest
{
  use UserTemporalPasswordAccessor;
}
